	'beforetoggle',
	'cancel',
	'canplay',
	'canplaythrough',
	'close',
	'durationchange',
	'emptied',
	'encrypted',
	'ended',
	'error',
	'load',
	'loadeddata',
	'loadedmetadata',
	'loadstart',
	'pause',
	'play',
	'playing',
	'progress',
	'ratechange',
	'resize',
	'seeked',
	'seeking',
	'stalled',
	'suspend',
	'timeupdate',
	'toggle',
	'volumechange',
	'waiting',
